#include "EventSystem.h"
#include <iostream>
#include <algorithm>
#include <limits>
#include <stdexcept>
#include <ctime>
#include <iomanip>
EventSystem::EventSystem(std::string folder):files(folder),nextEventId(1),nextParticipantId(1),nextOrganizerId(1),nextRegistrationId(1){
 files.loadEvents(events);files.loadParticipants(participants);files.loadOrganizers(organizers);files.loadRegistrations(registrations);
 for(auto& x:events)nextEventId=std::max(nextEventId,x.getId()+1);
 for(auto& x:participants)nextParticipantId=std::max(nextParticipantId,x.getId()+1);
 for(auto& x:organizers)nextOrganizerId=std::max(nextOrganizerId,x.getId()+1);
 for(auto& x:registrations)nextRegistrationId=std::max(nextRegistrationId,x.getId()+1);
}
void EventSystem::persist(){if(!files.saveEvents(events)||!files.saveParticipants(participants)||!files.saveOrganizers(organizers)||!files.saveRegistrations(registrations))throw std::runtime_error("Could not save data. Check the Data folder path and permissions.");}
bool EventSystem::emailValid(const std::string& e)const{return e.find('@')!=std::string::npos&&e.find('.')!=std::string::npos&&e.find('@')<e.rfind('.');}
void EventSystem::listEvents()const{std::cout<<"\nID | Event | Date | Venue | Capacity | Registered | Seats left\n";for(const auto& e:events)std::cout<<e.getId()<<" | "<<e.getName()<<" | "<<e.getDate()<<" | "<<e.getVenue()<<" | "<<e.getCapacity()<<" | "<<e.getRegistered()<<" | "<<e.seatsLeft()<<'\n';if(events.empty())std::cout<<"No events found.\n";}
void EventSystem::listParticipants()const{std::cout<<"\nID | Participant | Email\n";for(const auto& p:participants)std::cout<<p.getId()<<" | "<<p.getName()<<" | "<<p.getEmail()<<'\n';if(participants.empty())std::cout<<"No participants found.\n";}
void EventSystem::listOrganizers()const{std::cout<<"\nID | Organizer | Department\n";for(const auto& o:organizers)std::cout<<o.getId()<<" | "<<o.getName()<<" | "<<o.getDepartment()<<'\n';if(organizers.empty())std::cout<<"No organizers found.\n";}
void EventSystem::listRegistrations()const{std::cout<<"\nRegistration ID | Participant ID | Event ID | Created at\n";for(const auto& r:registrations)std::cout<<r.getId()<<" | "<<r.getParticipantId()<<" | "<<r.getEventId()<<" | "<<r.getTimestamp()<<'\n';if(registrations.empty())std::cout<<"No registrations found.\n";}
void EventSystem::addEvent(){std::string n,d,v;int cap;std::cout<<"Event name: ";std::getline(std::cin,n);std::cout<<"Date (YYYY-MM-DD): ";std::getline(std::cin,d);std::cout<<"Venue: ";std::getline(std::cin,v);std::cout<<"Capacity: ";if(!(std::cin>>cap)){std::cin.clear();std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');throw std::invalid_argument("Capacity must be a number.");}std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');if(n.empty()||d.empty()||v.empty()||cap<=0)throw std::invalid_argument("Fields cannot be empty and capacity must be positive.");events.emplace_back(nextEventId++,n,d,v,cap,0);persist();std::cout<<"Event added.\n";}
void EventSystem::addParticipant(){std::string n,e;std::cout<<"Participant name: ";std::getline(std::cin,n);std::cout<<"Email: ";std::getline(std::cin,e);if(n.empty()||!emailValid(e))throw std::invalid_argument("Enter a name and a valid email address.");for(auto& p:participants)if(p.getEmail()==e)throw std::invalid_argument("This email is already registered.");participants.emplace_back(nextParticipantId++,n,e);persist();std::cout<<"Participant added.\n";}
void EventSystem::addOrganizer(){std::string n,d;std::cout<<"Organizer name: ";std::getline(std::cin,n);std::cout<<"Department/team: ";std::getline(std::cin,d);if(n.empty()||d.empty())throw std::invalid_argument("Fields cannot be empty.");organizers.emplace_back(nextOrganizerId++,n,d);persist();std::cout<<"Organizer added.\n";}
void EventSystem::registerParticipant(){listParticipants();int p,e;std::cout<<"Participant ID: ";if(!(std::cin>>p)){std::cin.clear();std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');throw std::invalid_argument("ID must be numeric.");}std::cout<<"Event ID: ";if(!(std::cin>>e)){std::cin.clear();std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');throw std::invalid_argument("ID must be numeric.");}std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');auto pi=std::find_if(participants.begin(),participants.end(),[p](const Participant& x){return x.getId()==p;});auto ei=std::find_if(events.begin(),events.end(),[e](const Event& x){return x.getId()==e;});if(pi==participants.end()||ei==events.end())throw std::invalid_argument("Participant or event ID not found.");for(auto& r:registrations)if(r.getParticipantId()==p&&r.getEventId()==e)throw std::invalid_argument("Duplicate registration is not allowed.");ei->addRegistration();std::time_t now=std::time(nullptr);std::tm* t=std::localtime(&now);char stamp[20];std::strftime(stamp,sizeof(stamp),"%Y-%m-%d %H:%M",t);registrations.emplace_back(nextRegistrationId++,p,e,stamp);persist();std::cout<<"Registration successful. Registration ID: "<<nextRegistrationId-1<<'\n';}
void EventSystem::cancelRegistration(){int id;listRegistrations();std::cout<<"Registration ID to cancel: ";if(!(std::cin>>id)){std::cin.clear();std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');throw std::invalid_argument("ID must be numeric.");}std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');auto it=std::find_if(registrations.begin(),registrations.end(),[id](const Registration& r){return r.getId()==id;});if(it==registrations.end())throw std::invalid_argument("Registration not found.");int eid=it->getEventId();auto ev=std::find_if(events.begin(),events.end(),[eid](const Event& e){return e.getId()==eid;});if(ev!=events.end())ev->removeRegistration();registrations.erase(it);persist();std::cout<<"Registration cancelled and seat released.\n";}
void EventSystem::run(){int c=0;do{std::cout<<"\n===== EVENT REGISTRATION SYSTEM =====\n1. List events\n2. Add event\n3. Add participant\n4. List participants\n5. Add organizer\n6. List organizers\n7. Register participant for event\n8. List registrations\n9. Cancel registration\n0. Save and exit\nChoose: ";if(!(std::cin>>c)){std::cin.clear();std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');std::cout<<"Please enter a numeric menu option.\n";continue;}std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');try{switch(c){case 1:listEvents();break;case 2:addEvent();break;case 3:addParticipant();break;case 4:listParticipants();break;case 5:addOrganizer();break;case 6:listOrganizers();break;case 7:registerParticipant();break;case 8:listRegistrations();break;case 9:cancelRegistration();break;case 0:persist();std::cout<<"Data saved. Goodbye.\n";break;default:std::cout<<"Invalid option.\n";}}catch(const std::exception& ex){std::cout<<"Error: "<<ex.what()<<'\n';}}while(c!=0);}
